referenceSolutions.javascript:
export function solve(root) {
  const lines = [];
  const walk = (n, d) => {
    const indent = "  ".repeat(d);
    if (typeof n === "string") lines.push(indent + n);
    else {
      lines.push(indent + "<" + n.tag + ">");
      for (const c of n.children) walk(c, d + 1);
      lines.push(indent + "</" + n.tag + ">");
    }
  };
  walk(root, 0);
  return lines.join("\n");
}

referenceSolutions.typescript:
export function solve(root: any): any {
  const lines: string[] = [];
  const walk = (n: any, d: number): void => {
    const indent = "  ".repeat(d);
    if (typeof n === "string") lines.push(indent + n);
    else {
      lines.push(indent + "<" + n.tag + ">");
      for (const c of n.children) walk(c, d + 1);
      lines.push(indent + "</" + n.tag + ">");
    }
  };
  walk(root, 0);
  return lines.join("\n");
}
